using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.InputSystem;using UnityEngine.InputSystem.UI;using TMPro;
public class GeneratorWireRepair:MonoBehaviour {
 public WoodlandMedicalSequence owner;public bool Opened{get;private set;}public bool Complete{get;private set;}public int ConnectedCount{get{int n=0;foreach(bool b in connected)if(b)n++;return n;}}
 bool[] connected=new bool[3];RectTransform panel;GameObject canvasObject;RectTransform[] sockets=new RectTransform[3],lines=new RectTransform[3];TextMeshProUGUI status;UnityEngine.UI.Button powerSwitch;TMP_FontAsset font;Sprite cableSprite;Texture2D cableTexture;int dragging=-1;CursorLockMode previousCursor;bool previousVisible;Color[] colors={new Color(.95f,.36f,.18f),new Color(.35f,.72f,1),new Color(1,.8f,.2f)};
 Vector2 Source(int id)=>new Vector2(-338,175-id*100);
 Vector2 Socket(int id)=>new Vector2(338,175-((id+2)%3)*100);
 public void Open(){if(Opened||owner.powered||owner.loading||owner.player.anatomy.Incapacitated)return;if(!canvasObject)Build();Opened=true;owner.player.ResetLean();if(owner.player.fieldKit&&owner.player.fieldKit.Open)owner.player.fieldKit.Close();owner.player.cinematicLocked=true;previousCursor=Cursor.lockState;previousVisible=Cursor.visible;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;canvasObject.SetActive(true);Refresh();}
 public void Close(){if(!Opened)return;Opened=false;dragging=-1;canvasObject.SetActive(false);owner.player.cinematicLocked=false;Cursor.lockState=previousCursor;Cursor.visible=previousVisible;}
 public bool Connect(int wire,int socket){if(!Opened||wire<0||wire>2||socket!=wire||connected[wire]){if(status)status.text="Wrong terminal — match both colour and letter.";return false;}connected[wire]=true;Refresh();return true;}
 public bool SwitchOn(){if(!Opened||ConnectedCount!=3)return false;Complete=true;Close();owner.StartCoroutine(owner.StartGenerator());return true;}
 public void BeginDrag(int id){if(!Opened||connected[id])return;dragging=id;}
 public void EndDrag(Vector2 screen){if(dragging<0)return;int wire=dragging;dragging=-1;bool hit=false;for(int n=0;n<3;n++)if(RectTransformUtility.RectangleContainsScreenPoint(sockets[n],screen)){Connect(wire,n);hit=true;break;}if(!hit)status.text="Bring the loose wire onto its matching terminal.";DrawWire(wire,connected[wire]?Socket(wire):Source(wire)+Vector2.right*75);}
 void Update(){if(WoodlandDemoControls.Paused)return;if(!Opened)return;if(owner.player.anatomy.Incapacitated||(Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame)){Close();return;}if(dragging>=0&&Mouse.current!=null){RectTransformUtility.ScreenPointToLocalPointInRectangle(panel,Mouse.current.position.ReadValue(),null,out var local);DrawWire(dragging,local);}}
 void Refresh(){status.text=ConnectedCount==3?"Connections secure. Flick the switch to restore power.":"Drag each loose wire to its matching letter and colour.";powerSwitch.interactable=ConnectedCount==3;powerSwitch.GetComponentInChildren<TextMeshProUGUI>().text=ConnectedCount==3?"OFF  →  ON":"SWITCH LOCKED";for(int n=0;n<3;n++)DrawWire(n,connected[n]?Socket(n):Source(n)+Vector2.right*75);}
 void DrawWire(int id,Vector2 end){var root=lines[id];root.anchoredPosition=Vector2.zero;root.localRotation=Quaternion.identity;root.sizeDelta=Vector2.zero;var start=Source(id);for(int k=0;k<20;k++){RectTransform seg;if(k>=root.childCount){seg=Rect("Insulated cable",root,Vector2.zero,Vector2.zero);seg.pivot=new Vector2(0,.5f);var im=Image(seg,colors[id]);if(!cableSprite){cableTexture=new Texture2D(4,32,TextureFormat.RGBA32,false);for(int y=0;y<32;y++)for(int x=0;x<4;x++){float v=y/31f;float shade=.22f+.5f*Mathf.Sin(v*Mathf.PI)+.28f*Mathf.Exp(-Mathf.Pow((v-.7f)/.13f,2));cableTexture.SetPixel(x,y,new Color(shade,shade,shade,1));}cableTexture.Apply();cableSprite=Sprite.Create(cableTexture,new Rect(0,0,4,32),Vector2.one*.5f);}im.sprite=cableSprite;var shadow=seg.gameObject.AddComponent<UnityEngine.UI.Shadow>();shadow.effectColor=new Color(0,0,0,.65f);shadow.effectDistance=new Vector2(2,-3);}else seg=(RectTransform)root.GetChild(k);float a=k/20f,b=(k+1)/20f;var p=Vector2.Lerp(start,end,a)+Vector2.down*Mathf.Sin(a*Mathf.PI)*Mathf.Min(50,Vector2.Distance(start,end)*.14f);var q=Vector2.Lerp(start,end,b)+Vector2.down*Mathf.Sin(b*Mathf.PI)*Mathf.Min(50,Vector2.Distance(start,end)*.14f);var d=q-p;seg.anchoredPosition=p;seg.sizeDelta=new Vector2(d.magnitude+1,7);seg.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(d.y,d.x)*Mathf.Rad2Deg);}}
 RectTransform Rect(string name,Transform parent,Vector2 pos,Vector2 size){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(parent,false);var r=(RectTransform)g.transform;r.anchorMin=r.anchorMax=r.pivot=Vector2.one*.5f;r.anchoredPosition=pos;r.sizeDelta=size;return r;}
 UnityEngine.UI.Image Image(RectTransform r,Color c,bool hit=false){var im=r.gameObject.AddComponent<UnityEngine.UI.Image>();im.color=c;im.raycastTarget=hit;return im;}
 TextMeshProUGUI Label(Transform parent,string text,Vector2 pos,Vector2 size,int fontSize){var r=Rect("Label",parent,pos,size);var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.font=font;t.text=text;t.fontSize=fontSize;t.alignment=TextAlignmentOptions.Center;t.color=new Color(.86f,.89f,.82f);t.raycastTarget=false;return t;}
 void Build(){font=Resources.Load<TMP_FontAsset>("Fonts & Materials/LiberationSans SDF");canvasObject=new GameObject("Generator wire repair",typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler),typeof(UnityEngine.UI.GraphicRaycaster));canvasObject.transform.SetParent(transform,false);var canvas=canvasObject.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=200;var scaler=canvasObject.GetComponent<UnityEngine.UI.CanvasScaler>();scaler.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1280,720);scaler.matchWidthOrHeight=.5f;if(!EventSystem.current){var es=new GameObject("Repair EventSystem",typeof(EventSystem),typeof(InputSystemUIInputModule));es.transform.SetParent(transform,false);es.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();}
 var shade=Rect("Backdrop",canvasObject.transform,Vector2.zero,new Vector2(3000,2000));Image(shade,new Color(0,0,0,.65f),true);panel=Rect("Generator service panel",canvasObject.transform,Vector2.zero,new Vector2(760,510));var plate=panel.gameObject.AddComponent<UnityEngine.UI.RawImage>();plate.texture=Resources.Load<Texture2D>("Medical/GeneratorPanel");plate.raycastTarget=true;Label(panel,"AUXILIARY GENERATOR / SERVICE PANEL",new Vector2(0,285),new Vector2(710,45),25);Label(panel,"MATCH THE CONNECTIONS",new Vector2(0,238),new Vector2(650,35),17);
 for(int n=0;n<3;n++){lines[n]=Rect("Wire "+n,panel,Source(n),new Vector2(75,7));lines[n].pivot=new Vector2(0,.5f);}
 for(int n=0;n<3;n++){var plug=Rect("Loose wire "+n,panel,Source(n),new Vector2(52,52));Image(plug,new Color(colors[n].r,colors[n].g,colors[n].b,.25f),true);Label(plug,((char)('A'+n)).ToString(),Vector2.zero,new Vector2(50,40),26);var drag=plug.gameObject.AddComponent<GeneratorWireDrag>();drag.repair=this;drag.id=n;sockets[n]=Rect("Terminal "+n,panel,Socket(n),new Vector2(56,56));Image(sockets[n],new Color(colors[n].r,colors[n].g,colors[n].b,.25f),true);Label(sockets[n],((char)('A'+n)).ToString(),Vector2.zero,new Vector2(50,40),26);}
 status=Label(panel,"",new Vector2(-35,-190),new Vector2(500,60),18);var sw=Rect("Power switch",panel,new Vector2(282,-161),new Vector2(85,100));Image(sw,new Color(.19f,.31f,.23f,.015f),true);powerSwitch=sw.gameObject.AddComponent<UnityEngine.UI.Button>();powerSwitch.targetGraphic=sw.GetComponent<UnityEngine.UI.Image>();powerSwitch.onClick.AddListener(()=>SwitchOn());Label(sw,"SWITCH LOCKED",new Vector2(-90,0),new Vector2(80,35),19);Label(canvasObject.transform,"ESC · Close panel — connected wires are retained",new Vector2(0,-290),new Vector2(750,40),17);canvasObject.SetActive(false);}
 void OnDisable(){Close();}
 void OnDestroy(){if(cableSprite)Destroy(cableSprite);if(cableTexture)Destroy(cableTexture);}
 
}
public class GeneratorWireDrag:MonoBehaviour,IBeginDragHandler,IDragHandler,IEndDragHandler {
 public GeneratorWireRepair repair;public int id;
 public void OnBeginDrag(PointerEventData e){repair.BeginDrag(id);}public void OnDrag(PointerEventData e){}public void OnEndDrag(PointerEventData e){repair.EndDrag(e.position);}
}
